probe.script:
// Probe (coverage agent, 2026-10-16): can a life made at Yale reach bank.savings_notice through its home account?
import { readFileSync } from 'node:fs';
import { createSave, loadPlacesFor, loadSave } from '@/engine';
import { newLifeConfig, withFamily, type NewSaveConfig } from '@/engine/world/bootstrap';
import { addCountryHolidays } from '@/engine/content/holidays';
import { deserialise, serialise } from '@/engine/persistence/adapter';
import { homeAccountRefusal } from '@/engine/systems/homeaccount';
for (const country of ['uk', 'de', 'jp', 'fr']) addCountryHolidays(country, readFileSync(`public/holidays/${country}.tsv`, 'utf8'));
for (const wealth of ['modest', 'comfortable', 'wealthy', 'inherited'] as const) {
  for (const bank of ['de-deutsche-bank', 'de-postbank', 'de-berliner-sparkasse']) {
    const config: NewSaveConfig = { ...withFamily(newLifeConfig(), wealth), homeRegionId: 'de-be-berlin', firstName: 'Ada', lastName: 'Cole', pronouns: 'she/her', bankId: 'us-chase', priorResidence: { cityId: 'de-be-berlin', fromYear: 2002, fromMonth: 6 }, homeBankId: bank };
    const why = homeAccountRefusal(config, bank);
    if (why) { console.log(wealth, bank, 'REFUSED:', why); continue; }
    const sim = createSave(1, 'cov-sn', config);
    await loadPlacesFor(sim.universe);
    const mine = Object.values(sim.universe.accounts).filter((a) => !a.nominal && a.ownerId === sim.player.id && !a.closedAt);
    const savings = mine.find((a) => a.bankId === bank && a.kind === 'savings');
    console.log(wealth, bank, 'accounts:', mine.map((a) => `${a.name}@${a.bankId}:${a.balance}${a.held !== undefined ? `(held ${a.held})` : ''}`).join(', '));
    if (!savings) continue;
    const r = sim.execute<{ closed: string; on?: number }>({ kind: 'bank.close_savings', payload: { accountId: savings.id } });
    console.log('  close_savings:', r.ok ? JSON.stringify(r.value) : r.error, r.ok && r.value?.on ? new Date(r.value.on).toISOString() : '');
    if (r.ok && r.value?.on) {
      const reloaded = loadSave(deserialise(serialise(sim.universe)) as never);
      reloaded.advanceTo(r.value.on + 3_600_000);
      const s2 = reloaded.universe.accounts[savings.id]!;
      const notes = reloaded.universe.notifications?.filter?.((n: { title: string }) => /Closed/.test(n.title)).map((n: { title: string; body: string }) => `${n.title}: ${n.body}`) ?? [];
      console.log('  after notice: closedAt', s2.closedAt ? new Date(s2.closedAt).toISOString() : 'open', 'balance', s2.balance, '|', notes.slice(-2).join(' || '));
    }
  }
}
